def find_release_month(title, artists):
    results = apis.spotify.search_songs(query=title, page_limit=20)
    artist_list = [a.strip() for a in artists.split(',')]
    for song in results:
        if song['title'] == title:
            # Check if all artists match
            song_artists = [a['name'] for a in song['artists']]
            if all(a in song_artists for a in artist_list):
                release_date = datetime.fromisoformat(song['release_date'])
                return f"{release_date.month:02d}/{release_date.year}"
    return None

# Test with first song
